def calculate_cumulative_utilization(task_set, up_to_task_index):
    cumulative_U = 0.0
    for j in range(up_to_task_index + 1):
        task_j = task_set[j] # Assuming task_set is 0-indexed and sorted by priority
        cumulative_U += calculate_task_utilization(task_j)
    return cumulative_U

def calculate_total_system_utilization(task_set):
    return calculate_cumulative_utilization(task_set, len(task_set) - 1)

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return (a * b) // gcd(a, b)

def calculate_hp_busy_period_and_hyperperiod(higher_priority_tasks):
    U_hp_total = 0.0
    sum_C_hp = 0
    periods_hp = []

    for task_j in higher_priority_tasks:
        U_hp_total += task_j.C / task_j.T
        sum_C_hp += task_j.C
        periods_hp.append(task_j.T)

    if U_hp_total >= 1:
        S_i_minus_1_total = float('inf') # Unbounded busy period
    else:
        S_i_minus_1_total = sum_C_hp / (1 - U_hp_total)

    H_i_minus_1_total = 1
    if periods_hp:
        for p in periods_hp:
            H_i_minus_1_total = lcm(H_i_minus_1_total, p)

    return S_i_minus_1_total, H_i_minus_1_total

def calculate_wcrt_cost(Z_i_C_i_L_i_val, cost_init, cost_fixed_i_minus_1, cost_sum):
    total_cost = cost_init + Z_i_C_i_L_i_val * (cost_fixed_i_minus_1 + cost_sum)
    return total_cost

import math

def calculate_period_spread(task_set):
    if not task_set:
        return 0.0

    # Assuming task_set is sorted by priority, task_set[0] is highest, task_set[-1] is lowest
    T_1 = task_set[0].T
    T_n = task_set[-1].T

    if T_1 == 0:
        return float('inf') # Or handle as error

    return math.log(T_n / T_1)
